{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE snitch_db.maplemonk.rolling_30_days_dashboard AS WITH capsule_launch AS ( SELECT CAPSULE, LAUNCH_DATE FROM VALUES (\'Street FC\', \'2026-06-23\'::DATE), (\'Street FC Plus\', \'2026-06-23\'::DATE), (\'botanical THEME\', \'2026-07-11\'::DATE), (\'Embroided Shirts\', \'2026-07-16\'::DATE), (\'GOLF POLO THEME\', \'2026-07-27\'::DATE), (\'PHOTO PRINT\', \'2026-08-06\'::DATE), (\'Try Less Denim\', \'2026-08-14\'::DATE), (\'Festive - 1\', NULL), (\'Printed Shirts\', \'2026-09-04\'::DATE), (\'Luxe\', \'2026-09-18\'::DATE), (\'Technical\', \'2026-09-24\'::DATE) AS t(CAPSULE, LAUNCH_DATE) ), sku_mapping AS ( SELECT DISTINCT UPPER(TRIM(SKU)) AS SKU, TRIM(COLLECTION) AS CAPSULE FROM snitch_db.maplemonk.collection_sku_mapped_sheet1 WHERE SKU IS NOT NULL AND COLLECTION IS NOT NULL ), last_30_days AS ( SELECT UPPER(TRIM(h.SKU_GROUP)) AS SKU_GROUP, sm.CAPSULE, cl.LAUNCH_DATE, SUM( CASE WHEN LOWER(TRIM(sm.CAPSULE)) = \'technical\' AND cl.LAUNCH_DATE IS NOT NULL AND DATEDIFF( DAY, cl.LAUNCH_DATE, CURRENT_DATE() ) < 30 THEN CASE WHEN TO_DATE(h.DATE) >= cl.LAUNCH_DATE THEN h.GROSS_QUANTITY ELSE 0 END ELSE CASE WHEN TO_DATE(h.DATE) >= CURRENT_DATE() - 30 THEN h.GROSS_QUANTITY ELSE 0 END END ) AS LAST_30_QTY, SUM( CASE WHEN LOWER(TRIM(sm.CAPSULE)) = \'technical\' AND cl.LAUNCH_DATE IS NOT NULL AND DATEDIFF( DAY, cl.LAUNCH_DATE, CURRENT_DATE() ) < 30 THEN CASE WHEN TO_DATE(h.DATE) >= cl.LAUNCH_DATE THEN h.GROSS_SALES ELSE 0 END ELSE CASE WHEN TO_DATE(h.DATE) >= CURRENT_DATE() - 30 THEN h.GROSS_SALES ELSE 0 END END ) AS LAST_30_GROSS_SALES, SUM( CASE WHEN LOWER(TRIM(sm.CAPSULE)) = \'technical\' AND cl.LAUNCH_DATE IS NOT NULL AND DATEDIFF( DAY, cl.LAUNCH_DATE, CURRENT_DATE() ) < 30 THEN CASE WHEN TO_DATE(h.DATE) >= cl.LAUNCH_DATE THEN h.DISCOUNT_AMOUNT ELSE 0 END ELSE CASE WHEN TO_DATE(h.DATE) >= CURRENT_DATE() - 30 THEN h.DISCOUNT_AMOUNT ELSE 0 END END ) AS LAST_30_DISCOUNT, ROUND( SUM( CASE WHEN LOWER(TRIM(sm.CAPSULE)) = \'technical\' AND cl.LAUNCH_DATE IS NOT NULL AND DATEDIFF( DAY, cl.LAUNCH_DATE, CURRENT_DATE() ) < 30 THEN CASE WHEN TO_DATE(h.DATE) >= cl.LAUNCH_DATE THEN h.GROSS_SALES ELSE 0 END ELSE CASE WHEN TO_DATE(h.DATE) >= CURRENT_DATE() - 30 THEN h.GROSS_SALES ELSE 0 END END ) / NULLIF( SUM( CASE WHEN LOWER(TRIM(sm.CAPSULE)) = \'technical\' AND cl.LAUNCH_DATE IS NOT NULL AND DATEDIFF( DAY, cl.LAUNCH_DATE, CURRENT_DATE() ) < 30 THEN CASE WHEN TO_DATE(h.DATE) >= cl.LAUNCH_DATE THEN h.GROSS_QUANTITY ELSE 0 END ELSE CASE WHEN TO_DATE(h.DATE) >= CURRENT_DATE() - 30 THEN h.GROSS_QUANTITY ELSE 0 END END ), 0 ), 2 ) AS LAST_30_ASP FROM snitch_db.maplemonk.horizontal_sales_categories h INNER JOIN sku_mapping sm ON UPPER(TRIM(h.SKU_GROUP)) = UPPER(TRIM(sm.SKU)) LEFT JOIN capsule_launch cl ON LOWER(TRIM(sm.CAPSULE)) = LOWER(TRIM(cl.CAPSULE)) GROUP BY UPPER(TRIM(h.SKU_GROUP)), sm.CAPSULE, cl.LAUNCH_DATE ), first_sales AS ( SELECT UPPER(TRIM(SKU_GROUP)) AS SKU_GROUP, MIN(DATE) AS FIRST_SALE_DATE FROM snitch_db.maplemonk.horizontal_sales_categories WHERE GROSS_QUANTITY > 0 GROUP BY 1 ), sales_periods AS ( SELECT UPPER(TRIM(h.SKU_GROUP)) AS SKU_GROUP, sm.CAPSULE, cl.LAUNCH_DATE, SUM( CASE WHEN LOWER(TRIM(sm.CAPSULE)) = \'technical\' AND cl.LAUNCH_DATE IS NOT NULL AND DATEDIFF( DAY, cl.LAUNCH_DATE, CURRENT_DATE() ) < 30 THEN CASE WHEN TO_DATE(h.DATE) >= cl.LAUNCH_DATE THEN h.GROSS_QUANTITY ELSE 0 END WHEN LOWER(TRIM(sm.CAPSULE)) = \'technical\' THEN CASE WHEN TO_DATE(h.DATE) >= CURRENT_DATE() - 30 THEN h.GROSS_QUANTITY ELSE 0 END ELSE CASE WHEN TO_DATE(h.DATE) >= fs.FIRST_SALE_DATE THEN h.GROSS_QUANTITY ELSE 0 END END ) AS CUMULATIVE_SALES_QTY, SUM( CASE WHEN cl.LAUNCH_DATE IS NOT NULL AND TO_DATE(h.DATE) >= cl.LAUNCH_DATE THEN h.GROSS_QUANTITY ELSE 0 END ) AS LAUNCH_TO_DATE_SALES_QTY FROM snitch_db.maplemonk.horizontal_sales_categories h INNER JOIN sku_mapping sm ON UPPER(TRIM(h.SKU_GROUP)) = UPPER(TRIM(sm.SKU)) LEFT JOIN capsule_launch cl ON LOWER(TRIM(sm.CAPSULE)) = LOWER(TRIM(cl.CAPSULE)) INNER JOIN first_sales fs ON UPPER(TRIM(h.SKU_GROUP)) = UPPER(TRIM(fs.SKU_GROUP)) GROUP BY UPPER(TRIM(h.SKU_GROUP)), sm.CAPSULE, cl.LAUNCH_DATE ), inwards AS ( SELECT UPPER(TRIM(SKUGROUP)) AS SKU_GROUP, SUM( PUTAWAY_COMPLETED_QUANTITY ) AS TOTAL_INWARD_QTY, SUM( CASE WHEN PUTAWAY_COMPLETED_DATE::DATE >= CURRENT_DATE() - 30 THEN PUTAWAY_COMPLETED_QUANTITY ELSE 0 END ) AS LAST_30_INWARD_QTY FROM snitch_db.maplemonk.putaway_tracking WHERE LOWER(FINAL_TYPE) LIKE \'new%\' GROUP BY UPPER(TRIM(SKUGROUP)) ), rolling_30_metrics AS ( SELECT l.SKU_GROUP, l.CAPSULE, l.LAUNCH_DATE, l.LAST_30_QTY, l.LAST_30_GROSS_SALES, l.LAST_30_DISCOUNT, l.LAST_30_ASP, CASE WHEN LOWER(TRIM(l.CAPSULE)) = \'technical\' AND l.LAUNCH_DATE IS NOT NULL AND DATEDIFF( DAY, l.LAUNCH_DATE, CURRENT_DATE() ) < 30 THEN i.LAST_30_INWARD_QTY ELSE i.TOTAL_INWARD_QTY END AS TOTAL_INWARD_QTY, fs.FIRST_SALE_DATE, sp.CUMULATIVE_SALES_QTY, sp.LAUNCH_TO_DATE_SALES_QTY, CASE WHEN LOWER(TRIM(l.CAPSULE)) = \'technical\' THEN LEAST( DATEDIFF( DAY, l.LAUNCH_DATE, CURRENT_DATE() ), 30 ) ELSE DATEDIFF( DAY, fs.FIRST_SALE_DATE, CURRENT_DATE() ) END AS DAYS_ACTIVE, DATEDIFF( DAY, l.LAUNCH_DATE, CURRENT_DATE() ) AS DAYS_SINCE_LAUNCH, ROUND( sp.CUMULATIVE_SALES_QTY / NULLIF( CASE WHEN LOWER(TRIM(l.CAPSULE)) = \'technical\' AND l.LAUNCH_DATE IS NOT NULL AND DATEDIFF( DAY, l.LAUNCH_DATE, CURRENT_DATE() ) < 30 THEN i.LAST_30_INWARD_QTY ELSE i.TOTAL_INWARD_QTY END, 0 ) * 100, 2 ) AS STR_PERCENT_SOLD, ROUND( l.LAST_30_QTY / NULLIF( CASE WHEN LOWER(TRIM(l.CAPSULE)) = \'technical\' AND l.LAUNCH_DATE IS NOT NULL AND DATEDIFF( DAY, l.LAUNCH_DATE, CURRENT_DATE() ) < 30 THEN i.LAST_30_INWARD_QTY ELSE i.TOTAL_INWARD_QTY END, 0 ) * 100, 2 ) AS LAST_30_STR, CASE WHEN l.LAUNCH_DATE IS NULL THEN NULL WHEN DATEDIFF( DAY, l.LAUNCH_DATE, CURRENT_DATE() ) = 0 THEN NULL WHEN DATEDIFF( DAY, l.LAUNCH_DATE, CURRENT_DATE() ) < 30 THEN LEAST( ROUND( ( l.LAST_30_QTY / NULLIF( CASE WHEN LOWER(TRIM(l.CAPSULE)) = \'technical\' THEN i.LAST_30_INWARD_QTY ELSE i.TOTAL_INWARD_QTY END, 0 ) ) * ( 30.0 / DATEDIFF( DAY, l.LAUNCH_DATE, CURRENT_DATE() ) ) * 100, 2 ), 100 ) ELSE ROUND( l.LAST_30_QTY / NULLIF( CASE WHEN LOWER(TRIM(l.CAPSULE)) = \'technical\' THEN i.LAST_30_INWARD_QTY ELSE i.TOTAL_INWARD_QTY END, 0 ) * 100, 2 ) END AS NORMALIZED_30_STR FROM last_30_days l LEFT JOIN inwards i ON UPPER(TRIM(l.SKU_GROUP)) = UPPER(TRIM(i.SKU_GROUP)) LEFT JOIN first_sales fs ON UPPER(TRIM(l.SKU_GROUP)) = UPPER(TRIM(fs.SKU_GROUP)) LEFT JOIN sales_periods sp ON UPPER(TRIM(l.SKU_GROUP)) = UPPER(TRIM(sp.SKU_GROUP)) AND LOWER(TRIM(l.CAPSULE)) = LOWER(TRIM(sp.CAPSULE)) ) SELECT r30.*, r30.LAST_30_STR AS STR, CASE WHEN LOWER(TRIM(r30.CAPSULE)) IN ( \'embroided shirts\', \'botanical theme\', \'street fc\', \'street fc plus\', \'golf polo theme\', \'photo print\', \'try less denim\', \'printed shirts\', \'luxe\', \'technical\' ) THEN \'YES\' ELSE \'NO\' END AS FOCUS_CAPSULE FROM rolling_30_metrics r30 ORDER BY LAST_30_GROSS_SALES DESC;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from SNITCH_DB.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            